/* SheetJS xlsx 0.18.5 loader. Kept at this local filename so index.html can load it with ./xlsx.full.min.js. */
document.write('<script src="https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js"><\/script>');

/* Cross-verification export extension
 * results.과제번호 -> ingcontract F열(과제번호) 매칭
 * ingcontract H열=과제명, O열=연구시작일자, Q열=연구종료일자
 * 화면 결과표는 유지하고 Excel/CSV 다운로드 레이아웃에 과제정보를 보강합니다.
 */
window.addEventListener('DOMContentLoaded', function () {
  function clean(v) {
    return v === null || v === undefined ? '' : String(v).trim();
  }

  function formatDate(v) {
    if (v === null || v === undefined || v === '') return '';
    if (typeof v === 'number' && window.XLSX && XLSX.SSF && XLSX.SSF.parse_date_code) {
      const d = XLSX.SSF.parse_date_code(v);
      if (d && d.y) {
        return String(d.y).padStart(4,'0') + '-' + String(d.m).padStart(2,'0') + '-' + String(d.d).padStart(2,'0');
      }
    }
    const s = clean(v);
    const m = s.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})/);
    if (m) return m[1] + '-' + m[2].padStart(2,'0') + '-' + m[3].padStart(2,'0');
    return s;
  }

  async function enrichResultsFromIngcontract() {
    if (typeof files === 'undefined' || !files.ing || typeof readExcel !== 'function') return;

    const ingRows = await readExcel(files.ing);
    const projectInfoMap = new Map();
    const start = typeof dataStart === 'function' ? dataStart(ingRows) : 1;

    for (let r = start; r < ingRows.length; r++) {
      const row = ingRows[r] || [];
      const project = clean(row[5]); // F열: 과제번호
      if (!project) continue;

      projectInfoMap.set(project, {
        '과제명': clean(row[7]),              // H열
        '연구시작일자': formatDate(row[14]),  // O열
        '연구종료일자': formatDate(row[16])   // Q열
      });
    }

    if (typeof results !== 'undefined') {
      results = results.map(function (r) {
        const info = projectInfoMap.get(clean(r['과제번호'])) || {};
        return Object.assign({}, r, {
          '과제명': info['과제명'] || '',
          '연구시작일자': info['연구시작일자'] || '',
          '연구종료일자': info['연구종료일자'] || ''
        });
      });
    }
  }

  window.exportRows = function () {
    const source = (typeof results !== 'undefined') ? results : [];
    return source.map(function (r) {
      return {
        '상태': r['상태'],
        '직번': r['직번'],
        '성명': r['성명'],
        '과제번호': r['과제번호'],
        '과제명': r['과제명'] || '',
        '연구시작일자': r['연구시작일자'] || '',
        '연구종료일자': r['연구종료일자'] || '',
        '년도': r['년도'],
        '불일치월': r['불일치월'],
        '계약관리 지급액': r['계약관리 지급액'],
        '참여인력 예정액': r['참여인력 예정액'],
        '차액': r['차액']
      };
    });
  };

  ['xlsxBtn', 'csvBtn'].forEach(function (id) {
    const btn = document.getElementById(id);
    if (!btn) return;

    btn.addEventListener('click', async function (e) {
      e.stopImmediatePropagation();
      try {
        await enrichResultsFromIngcontract();
      } catch (err) {
        alert('ingcontract 과제정보 처리 중 오류: ' + (err && err.message ? err.message : err));
        return;
      }

      if (typeof XLSX === 'undefined') {
        alert('Excel 처리 라이브러리를 불러오지 못했습니다.');
        return;
      }

      const ws = XLSX.utils.json_to_sheet(window.exportRows());
      if (id === 'xlsxBtn') {
        const wb = XLSX.utils.book_new();
        XLSX.utils.book_append_sheet(wb, ws, '검증결과');
        XLSX.writeFile(wb, '연구인력_월별인건비_검증결과.xlsx');
      } else {
        const csv = '\ufeff' + XLSX.utils.sheet_to_csv(ws);
        const a = document.createElement('a');
        a.href = URL.createObjectURL(new Blob([csv], {type:'text/csv;charset=utf-8'}));
        a.download = '연구인력_월별인건비_검증결과.csv';
        a.click();
        URL.revokeObjectURL(a.href);
      }
    }, true);
  });
});
